            uiManager.bind('credibilityDisplay', 'domainState.credibility',
                function(v) { return Math.round(v); });
            uiManager.bind('trustDisplay', 'domainState.audienceTrust',
                function(v) { return Math.round(v); });
            uiManager.bind('ethicsDisplay', 'domainState.ethicsScore',
                function(v) { return Math.round(v); });
        }

