        getChartData(state) {
            var roundLabels = [this._t('audience_board'), this._t('audience_employee'), this._t('audience_media')];
            var labels = state.domainState.cesHistory.map(function(_, i) { return roundLabels[i] || ('R' + (i + 1)); });
            return {
                cesChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.cesHistory }]
                },
                dimensionChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.logosHistory },
                        { data: state.domainState.ethosHistory },
                        { data: state.domainState.pathosHistory },
                        { data: state.domainState.ethicsHistory }
                    ]
                }
            };
        }

        // what the run did, read from its own history: the mistakes of the teaching block, per room CES,
        // the lowest room, and whether the board story differed from the other rooms
        _debriefFacts(history) {
            var f = { mistakes: [], rooms: [], turn: -1, spin: false, allAbove70: false, emot: 0, layoffDir: 0 };
            var d1 = history[0] && history[0].decisions;
            var d2 = history[1] && history[1].decisions;
            var d3 = history[2] && history[2].decisions;
            f.rooms = history.map(function(r) { return r.results ? r.results.ces : 0; });
            f.allAbove70 = history.length === 3 && f.rooms.every(function(c) { return c >= 70; });
            var low = 101;
            for (var i = 0; i < f.rooms.length; i++) { if (f.rooms[i] < low) { low = f.rooms[i]; f.turn = i; } }
            if (d1) {
                f.spin = this._boardSpin(d1);
                if (d1.scqaLead === 2) f.mistakes.push('m1');
                if (d1.marginTreat === 3) f.mistakes.push('margin');
                if (d1.viz1 === 2 || d1.viz2 === 2) f.mistakes.push('viz');
            }
            if (d2 && history.length >= 2) {
                f.emot = d2.emotCal; f.layoffDir = d2.layoffDir;
                if (d2.layoffDir <= 2) f.mistakes.push('m2');
                if (d2.emotCal >= 7) f.mistakes.push('m3');
            }
            if (d3 && history.length >= 3) {
                if (d3.bridgeStrat === 2 || d3.hostileResp === 1) f.mistakes.push('m4');
                if (d3.bridgeStrat === 3) f.mistakes.push('m5');
            }
            return f;
        }

        _debriefLines(f, T) {
            var lines = [];
            var rooms = [T('audience_board'), T('audience_employee'), T('audience_media')];
            if (f.turn >= 0) {
                var tp = T('dbf_turn').replace('{room}', rooms[f.turn] || '').replace('{n}', f.rooms[f.turn]);
                if (f.rooms[f.turn] < 70 && f.rooms.length === 3) tp += ' ' + T('dbf_turn_bonus');
                lines.push({ kind: 'turn', text: tp });
            }
            f.mistakes.forEach(function(m) {
                var txt = T('dbf_' + m);
                if (m === 'm2') txt = txt.replace('{n}', f.layoffDir);
                if (m === 'm3') { txt = txt.replace('{n}', f.emot); if (f.emot === 10) txt += ' ' + T('dbf_m3_ethics'); }
                lines.push({ kind: 'mistake', text: txt });
            });
            if (f.spin && f.allAbove70) lines.push({ kind: 'mistake', text: T('dbf_coh_lost') });
            if (!f.mistakes.length && f.rooms.length === 3) lines.push({ kind: 'clean', text: T('dbf_clean') });
            return lines;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var cesScores = history.map(function(r) { return r.results ? r.results.ces : 0; });
            var totalCES = cesScores.reduce(function(s, v) { return s + v; }, 0);
            var avgCES = Math.round(totalCES / cesScores.length);
            var bonus = 0;

            if (history.length === 3) {
                var allAbove70 = cesScores.every(function(c) { return c >= 70; });
                var d1 = history[0] && history[0].decisions;
                if (allAbove70 && !(d1 && this._boardSpin(d1))) bonus = 15;
            }

            var finalScore = Math.min(100, avgCES + bonus);
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var perfId = 'fail';
            if (finalScore >= 85) perfId = 'trusted';
            else if (finalScore >= 70) perfId = 'competent';
            else if (finalScore >= 55) perfId = 'inconsistent';
            else if (finalScore >= 40) perfId = 'gap';
            var performance = T('perf_' + perfId);

            var facts = this._debriefFacts(history);
            var insights = [];
            if (finalScore >= 85) insights.push(T('insight_85'));
            else if (finalScore >= 70) { if (!facts.allAbove70) insights.push(T('insight_70')); }
            else if (finalScore >= 55) insights.push(T('insight_55'));
            else if (finalScore >= 40) insights.push(T('insight_40'));
            else insights.push(T('insight_fail'));

            if (bonus > 0) insights.push(T('insight_bonus'));
            this._debriefLines(facts, T).forEach(function(l) { insights.push(l.text); });

            return {
                totalCES: finalScore,
                avgCES: avgCES,
                consistencyBonus: bonus,
                performance: performance,
                performanceLabel: performance,
                performanceKey: 'perf_' + perfId,
                overallScore: finalScore,
                totalScore: finalScore,
                score: finalScore,
                totalPeriods: history.length,
                rooms: facts.rooms,
                insights: insights
            };
        }

        // the closing debrief: verdict and score, CES per room, the turning point, what this run did, and two
        // questions for class (case, Simulation Linkage debrief prompts); rebuilt from the history in the
        // current language each time it is shown
        formatCompletionMessage(summary) {
            summary = summary || {};
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var st = window.mySimulation && window.mySimulation.state;
            var history = (st && st.history) || [];
            var tier = summary.performanceKey ? T(summary.performanceKey) : (summary.performanceLabel || summary.performance || '');
            var html = '<div class="usf-debrief-tier">' + tier + '</div>';
            html += '<p class="narrative-sim-debrief-score">' + T('dbf_score').replace('{n}', summary.totalCES).replace('{avg}', summary.avgCES).replace('{bonus}', summary.consistencyBonus || 0) + '</p>';
            var rooms = [T('audience_board'), T('audience_employee'), T('audience_media')];
            var ces = (summary.rooms || []).map(function(c, i) { return rooms[i] + ' ' + c; });
            if (ces.length) html += '<p class="narrative-sim-debrief-rooms">' + T('dbf_rooms') + ': ' + ces.join(' \u00b7 ') + '</p>';
            if (history.length) {
                var lines = this._debriefLines(this._debriefFacts(history), T);
                var turn = lines.filter(function(l) { return l.kind === 'turn'; });
                var rest = lines.filter(function(l) { return l.kind !== 'turn'; });
                if (turn.length) html += '<h4 class="usf-debrief-h">' + T('dbf_turn_h') + '</h4><p>' + turn[0].text + '</p>';
                if (rest.length) html += '<h4 class="usf-debrief-h">' + T('dbf_run_h') + '</h4><ul class="usf-debrief-list">' + rest.map(function(l) { return '<li>' + l.text + '</li>'; }).join('') + '</ul>';
            }
            html += '<h4 class="usf-debrief-h">' + T('dbf_q_h') + '</h4><ol class="usf-debrief-list"><li>' + T('dbf_q1') + '</li><li>' + T('dbf_q2') + '</li></ol>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.ces < 50) return window.mySimulation.t('hint_low_ces');
            if (results.ethics < 60) return window.mySimulation.t('hint_ethics_risk');
            if (results.ethos < 55) return window.mySimulation.t('hint_credibility');
            if (results.ces >= 75) return window.mySimulation.t('hint_strong');
            return null;
        }

